#include "rpg/battle_presentation.hpp"
#include <cmath>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace rpg;
using namespace rpg::presentation;
void check(bool ok){if(!ok){throw std::runtime_error("Presentation contract failed");}}
void shield_values(){Fighter f{{"A",Team::A,100,10,100},100};f.statuses.push_back({EffectKind::Shield,2,TickPolicy::NaturalOnly,1,10});check(shield_display(f).overlay_fraction==0.1);f.health=50;f.statuses[0].magnitude=5;check(shield_display(f).health_fraction==0.5 && shield_display(f).overlay_fraction==0.05);f.statuses[0].magnitude=10;check(shield_display(f).overlay_fraction==0.1);f.statuses[0].magnitude=1000;check(shield_display(f).overlay_fraction==0.5 && shield_display(f).points==1000);f.health=0;check(shield_display(f).overlay_fraction==0);}
void effect_popup(){Fighter f{{"A",Team::A,100,10,100},50};check(effect_details(f).size()==1);f.statuses={{EffectKind::Shield,2,TickPolicy::NaturalOnly,1,10},{EffectKind::Block,1,TickPolicy::EveryTurn,1}};auto lines=effect_details(f);check(lines.size()==4 && lines[0].find("Shield")!=std::string::npos && lines[2].find("Unable to act")!=std::string::npos);}
void candidates(){auto setup=team_reference_setup();setup.roster[0].speed=1000;VisualSession s(setup);auto v=s.state();auto ids=target_candidates(v,1);check(ids==std::vector<std::string>({"B1","B2","B3"}));check(target_candidates(v,3)==std::vector<std::string>({"A1"}));for(auto& f:v.combat.battle.fighters){if(f.definition.id=="B1"){f.health=0;}}check(target_candidates(v,1).size()==2);v.automatic=true;check(target_candidates(v,1).empty());v.automatic=false;v.stopped=true;check(target_candidates(v,1).empty());}
void passive_metadata(){auto setup=team_reference_setup();setup.roster[1].speed=1000;VisualSession s(setup);auto v=s.state();check(target_candidates(v,2).empty());auto lines=ability_details(v,2);check(!lines.empty() && lines[0]=="Preparacao");for(const auto& line:lines){check(line.find("Level:")==std::string::npos);}v.abilities[1].slot.level=4;v.abilities[1].slot.description="Original test description";lines=ability_details(v,2);check(lines[1]=="Level: 4" && lines[2]=="Original test description");}
void gesture_contract(){AbilityGesture g;g.press(1,0,7);check(g.release(0.1,7)==1u);g.press(2,1,7);check(!g.hold(1.4,7));check(g.hold(1.5,7)==2u);check(!g.hold(1.7,7));check(!g.release(1.8,7));g.press(3,2,7);check(!g.release(2.1,8));g.press(3,3,7);check(!g.hold(4,8));check(!g.active());g.press(1,std::numeric_limits<double>::quiet_NaN(),7);check(!g.active());}
void invalid_level(){auto setup=team_reference_setup();setup.loadouts[0].slots[0].level=0;bool rejected=false;try{VisualSession s(setup);}catch(const std::invalid_argument&){rejected=true;}check(rejected);}
int main(){try{shield_values();effect_popup();candidates();passive_metadata();gesture_contract();invalid_level();std::cout<<"PRESENTATION_TESTS_RESULT passed=6 total=6\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
